guardrail.bad:
// defined next to implementation — forces importers to depend on this package
type UserRepository interface {
    FindByID(id string) (*User, error)
    // ... 15 more methods
}

guardrail.good:
// defined in the consuming package — only the methods needed
type userFinder interface {
    FindByID(ctx context.Context, id string) (*User, error)
}

var wg sync.WaitGroup
wg.Add(1)
go func() {
    defer wg.Done()
    // ... work
}()
wg.Wait()

guardrail.bad:
var db *sql.DB  // package-level mutable state

func GetUser(id string) (*User, error) {
    return db.QueryRow(...)
}

guardrail.good:
type UserRepo struct {
    db *sql.DB
}

func NewUserRepo(db *sql.DB) *UserRepo { return &UserRepo{db: db} }

func (r *UserRepo) GetUser(ctx context.Context, id string) (*User, error) {
    return r.db.QueryRowContext(ctx, ...)
}

type NotFoundError struct {
    Resource string
    ID       string
}

func (e *NotFoundError) Error() string {
    return fmt.Sprintf("%s with ID %s not found", e.Resource, e.ID)
}

pattern.example:
func TestCalculate(t *testing.T) {
    tests := []struct {
        name     string
        a, b     int
        expected int
        wantErr  bool
    }{
        {"positive numbers", 2, 3, 5, false},
        {"negative numbers", -2, -3, -5, false},
        {"divide by zero", 1, 0, 0, true},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            result, err := Calculate(tt.a, tt.b)
            if tt.wantErr {
                if err == nil {
                    t.Error("expected error, got nil")
                }
                return
            }
            if err != nil {
                t.Fatalf("unexpected error: %v", err)
            }
            if result != tt.expected {
                t.Errorf("got %d, want %d", result, tt.expected)
            }
        })
    }
}

type UserService struct {
    repo   userFinder
    mailer emailSender
    logger *slog.Logger
}

func NewUserService(repo userFinder, mailer emailSender, logger *slog.Logger) *UserService {
    return &UserService{repo: repo, mailer: mailer, logger: logger}
}

func (h *UserHandler) GetUser(w http.ResponseWriter, r *http.Request) {
    ctx := r.Context()
    id := r.PathValue("id")

    user, err := h.service.GetUser(ctx, id)
    if err != nil {
        var notFound *NotFoundError
        if errors.As(err, &notFound) {
            http.Error(w, "not found", http.StatusNotFound)
            return
        }
        h.logger.ErrorContext(ctx, "get user failed", "id", id, "err", err)
        http.Error(w, "internal error", http.StatusInternalServerError)
        return
    }

    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(user)
}

func fetchAll(ctx context.Context, ids []string) ([]*User, error) {
    results := make(chan *User, len(ids))
    errs := make(chan error, len(ids))
    var wg sync.WaitGroup

    for _, id := range ids {
        wg.Add(1)
        go func(id string) {
            defer wg.Done()
            u, err := fetchUser(ctx, id)
            if err != nil {
                errs <- fmt.Errorf("fetch %s: %w", id, err)
                return
            }
            results <- u
        }(id)
    }

    wg.Wait()
    close(results)
    close(errs)

    if err := <-errs; err != nil {
        return nil, err
    }
    var users []*User
    for u := range results {
        users = append(users, u)
    }
    return users, nil
}

